package com.greenocean.backend;
import com.greenocean.backend.listener.planning.*;import com.greenocean.backend.listener.live.*;
import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;import com.greenocean.backend.account.repository.AccountRepository;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.live-support.enabled=true","greenocean.listener-support.duration-enabled=true","greenocean.listener-support.scheduling-enabled=true","greenocean.listener-support.booking-enabled=true","greenocean.listener-support.extension-enabled=true","greenocean.listener-support.followup-enabled=true"}) @ActiveProfiles("test")
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class PhaseN3ConcurrencyTest extends MigrationTestSupport {
 static final String SCHEMA="qa_n3_race_"+UUID.randomUUID().toString().replace("-","");
 @org.springframework.test.context.DynamicPropertySource static void schema(org.springframework.test.context.DynamicPropertyRegistry p){String url=System.getenv("GREENOCEAN_TEST_DB_URL");p.add("spring.datasource.url",()->url+(url.contains("?")?"&":"?")+"currentSchema="+SCHEMA+",public");p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.jpa.properties.hibernate.default_schema",()->SCHEMA);}
 @AfterAll static void drop(@Autowired JdbcTemplate db){db.execute("DROP SCHEMA "+SCHEMA+" CASCADE");}
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired ListenerCalendar calendar;@Autowired ListenerBookings bookings;@Autowired ListenerSupportPolicy policy;@Autowired LiveSupportService live;@Autowired AccountRepository accounts;@Autowired PlatformTransactionManager manager;
 @Autowired ListenerSessions sessions;PhaseIFixtures.Actor member,other,listener,staff;Instant start;UUID window;
 @BeforeEach void setup(){PhaseIFixtures.region(db);member=PhaseIFixtures.member(db,users,tokens);other=PhaseIFixtures.member(db,users,tokens);listener=PhaseIFixtures.member(db,users,tokens);staff=PhaseIFixtures.member(db,users,tokens);PhaseIFixtures.review(db,listener.id(),staff.id(),true);start=policy.now().plusSeconds(7200).truncatedTo(java.time.temporal.ChronoUnit.MINUTES);window=calendar.exception(listener.id(),new ListenerCalendar.ExceptionInput("UTC",start.atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),start.plusSeconds(14400).atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),null,null,true));live.setAvailability(listener.id(),listener.session(),0,true,null);}
 @AfterEach void clean(){db.execute("CREATE OR REPLACE FUNCTION listener_support_now() RETURNS TIMESTAMPTZ LANGUAGE SQL VOLATILE AS $$ SELECT clock_timestamp() $$");for(var a:List.of(member,other,listener,staff))new TransactionTemplate(manager).execute(s->{accounts.erase(a.id());return null;});}
 ListenerBookings.Reservation in(Instant time,UUID key){return new ListenerBookings.Reservation(listener.id(),time,key,false);}
 List<Object> race(Supplier<?> a,Supplier<?> b)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var go=new CountDownLatch(1);var x=pool.submit(()->{go.await();return outcome(a);});var y=pool.submit(()->{go.await();return outcome(b);});go.countDown();return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}}
 Object outcome(Supplier<?> f){try{return f.get();}catch(RuntimeException e){return e;}}
 long count(){return db.queryForObject("SELECT count(*) FROM listener_bookings WHERE member_id IN(?,?) AND status='CONFIRMED'",Long.class,member.id(),other.id());}

 LiveSupportView active(){var r=live.create(member.id(),UUID.randomUUID(),listener.id());live.accept(r.id(),listener.id());return live.activate(r.id(),member.id());}
 UUID proposal(UUID id){return(UUID)((Map<?,?>)sessions.request(id,member.id(),new ListenerSessions.Proposal(UUID.randomUUID())).get("extension")).get("id");}
 void clock(Instant at){db.execute("CREATE OR REPLACE FUNCTION listener_support_now() RETURNS TIMESTAMPTZ LANGUAGE SQL VOLATILE AS $$ SELECT '"+at+"'::timestamptz $$");}
 @Test @Tag("malicious") void concurrentParticipantApprovalsAddOnlyTenMinutes()throws Exception{var r=active();UUID id=proposal(r.id());var out=race(()->sessions.decide(r.id(),id,member.id(),true),()->sessions.decide(r.id(),id,listener.id(),true));assertThat(out).allMatch(Map.class::isInstance);var result=live.get(r.id(),member.id());assertThat(result.plannedEndsAt()).isEqualTo(r.plannedEndsAt().plusSeconds(600));assertThat(result.extensionSecondsUsed()).isEqualTo(600);}
 @Test @Tag("malicious") void duplicateApprovedRequestsNeverAddTwentyMinutes()throws Exception{var r=active();UUID id=proposal(r.id());sessions.decide(r.id(),id,listener.id(),true);race(()->sessions.decide(r.id(),id,listener.id(),true),()->sessions.decide(r.id(),id,member.id(),true));assertThat(live.get(r.id(),member.id()).plannedEndsAt()).isEqualTo(r.plannedEndsAt().plusSeconds(600));assertThat(db.queryForObject("SELECT count(*) FROM listener_session_extensions WHERE session_id=?",Integer.class,r.id())).isEqualTo(1);}
 @Test @Tag("malicious") void extensionVersusNextReservationHasOneCapacityWinner()throws Exception{var r=active();UUID id=proposal(r.id());Instant next=r.plannedEndsAt().plusSeconds(450);calendar.exception(listener.id(),new ListenerCalendar.ExceptionInput("UTC",next.atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),next.plusSeconds(3600).atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),null,null,true));race(()->sessions.decide(r.id(),id,listener.id(),true),()->bookings.reserve(other.id(),in(next,UUID.randomUUID())));long booked=count();assertThat(booked).isIn(0L,1L);assertThat(live.get(r.id(),member.id()).plannedEndsAt()).isEqualTo(booked==1?r.plannedEndsAt():r.plannedEndsAt().plusSeconds(600));}
 @Test @Tag("creative") void endingVersusApprovalNeverReopensSession()throws Exception{var r=active();UUID id=proposal(r.id());race(()->live.end(r.id(),member.id()),()->sessions.decide(r.id(),id,listener.id(),true));var result=live.get(r.id(),member.id());assertThat(result.status()).isEqualTo("COMPLETED");assertThat(result.extensionSecondsUsed()).isIn(0,600);assertThatThrownBy(()->live.requireSending(r.conversationId(),member.id(),UUID.randomUUID())).isInstanceOf(LiveSupportException.class);}
 @Test @Tag("creative") void reconnectAtDurationBoundaryCannotRestartClock()throws Exception{var r=active();db.update("UPDATE live_support_requests SET member_seen_at=clock_timestamp()-INTERVAL '50 seconds' WHERE id=?",r.id());assertThat(live.get(r.id(),member.id()).status()).isEqualTo("INTERRUPTED");clock(r.plannedEndsAt());race(()->live.pulse(r.id(),member.id()),()->live.pulse(r.id(),listener.id()));var result=live.get(r.id(),member.id());assertThat(result.status()).isEqualTo("COMPLETED");assertThat(result.plannedEndsAt()).isEqualTo(r.plannedEndsAt());}
 @Test @Tag("malicious") void expiredProposalVersusBothApprovalsHasNoExtension()throws Exception{var r=active();UUID id=proposal(r.id());clock(db.queryForObject("SELECT expires_at FROM listener_session_extensions WHERE id=?",OffsetDateTime.class,id).toInstant());race(()->sessions.decide(r.id(),id,member.id(),true),()->sessions.decide(r.id(),id,listener.id(),true));assertThat(live.get(r.id(),member.id()).plannedEndsAt()).isEqualTo(r.plannedEndsAt());assertThat(db.queryForObject("SELECT status FROM listener_session_extensions WHERE id=?",String.class,id)).isEqualTo("EXPIRED");}
}
